//! Cross-verification tests: compare Rust implementations against PyTorch
//! reference oracle values stored in `test_fixtures/dreamer_oracles.json`.
//!
//! Generated by `scripts/extract_dreamer_oracles.py` (or the numpy variant).
//! Re-run the script after updating the reference repo to catch drift.

#[cfg(test)]
mod tests {
    use burn::backend::NdArray;
    use burn::prelude::*;
    use burn::tensor::TensorData;

    type B = NdArray;

    const ORACLES: &str = include_str!("../../test_fixtures/dreamer_oracles.json");

    fn dev() -> <B as Backend>::Device {
        Default::default()
    }

    fn tensor_2d_from_json(val: &serde_json::Value) -> Tensor<B, 2> {
        let rows: Vec<Vec<f64>> = serde_json::from_value(val.clone()).unwrap();
        let n_rows = rows.len();
        let n_cols = rows[0].len();
        let flat: Vec<f32> = rows.into_iter().flatten().map(|v| v as f32).collect();
        Tensor::from_data(TensorData::new(flat, [n_rows, n_cols]), &dev())
    }

    fn tensor_1d_from_json(val: &serde_json::Value) -> Tensor<B, 1> {
        let data: Vec<f64> = serde_json::from_value(val.clone()).unwrap();
        let len = data.len();
        let f32_data: Vec<f32> = data.into_iter().map(|v| v as f32).collect();
        Tensor::from_data(TensorData::new(f32_data, [len]), &dev())
    }

    // ==== Barlow Twins loss ====

    #[test]
    fn barlow_twins_loss_matches_reference() {
        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let bt = &oracles["barlow_twins"];

        let z_a = tensor_2d_from_json(&bt["z_a"]);
        let z_b = tensor_2d_from_json(&bt["z_b"]);

        let config = crate::loss::representation::BarlowTwinsConfig {
            lambda: bt["alpha"].as_f64().unwrap() as f32,
        };

        let loss: f32 = crate::loss::representation::barlow_twins_loss(
            z_a, z_b, &config,
        )
        .into_scalar();

        let expected = bt["loss"].as_f64().unwrap() as f32;
        assert!(
            (loss - expected).abs() < 1e-2,
            "BT loss {loss} != reference {expected}"
        );
    }

    #[test]
    fn barlow_twins_cross_correlation_matches_reference() {
        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let bt = &oracles["barlow_twins"];

        let z_a = tensor_2d_from_json(&bt["z_a"]);
        let z_b = tensor_2d_from_json(&bt["z_b"]);
        let expected_c = tensor_2d_from_json(&bt["C"]);

        // Reproduce internal computation
        let z_a_norm = crate::loss::representation::batch_normalize(z_a);
        let z_b_norm = crate::loss::representation::batch_normalize(z_b);
        let c = z_a_norm.transpose().matmul(z_b_norm) / 8.0;

        let diff: f32 = (c - expected_c).abs().max().into_scalar();
        assert!(diff < 1e-3, "C matrix max element-wise diff = {diff}");
    }

    #[test]
    fn barlow_twins_on_diag_off_diag_components_match() {
        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let bt = &oracles["barlow_twins"];

        let expected_on = bt["on_diag"].as_f64().unwrap() as f32;
        let expected_off = bt["off_diag"].as_f64().unwrap() as f32;

        let z_a = tensor_2d_from_json(&bt["z_a"]);
        let z_b = tensor_2d_from_json(&bt["z_b"]);

        let z_a_norm = crate::loss::representation::batch_normalize(z_a);
        let z_b_norm = crate::loss::representation::batch_normalize(z_b);
        let c = z_a_norm.transpose().matmul(z_b_norm) / 8.0;

        let [dim, _] = c.dims();
        let eye = Tensor::<B, 2>::eye(dim, &dev());

        let diag_diff = (c.clone() - eye.clone()) * eye.clone();
        let on_diag: f32 = diag_diff.powf_scalar(2.0).sum().into_scalar();

        let off_mask = eye.neg() + 1.0;
        let off_diag_vals = c * off_mask;
        let off_diag: f32 = off_diag_vals.powf_scalar(2.0).sum().into_scalar();

        assert!(
            (on_diag - expected_on).abs() < 1e-1,
            "on_diag {on_diag} != reference {expected_on}"
        );
        assert!(
            (off_diag - expected_off).abs() < 1e-1,
            "off_diag {off_diag} != reference {expected_off}"
        );
    }

    // ==== Barlow Twins gradient flow ====

    #[test]
    fn barlow_twins_target_is_detached() {
        // Reference confirms z_b is detached (no gradient flows to it).
        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let btg = &oracles["barlow_twins_gradients"];
        assert_eq!(
            btg["z_b_has_grad"].as_bool().unwrap(),
            false,
            "reference confirms z_b is detached"
        );
    }

    #[test]
    fn barlow_twins_gradient_exists_on_z_a() {
        use burn::backend::Autodiff;
        type AB = Autodiff<NdArray>;

        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let btg = &oracles["barlow_twins_gradients"];

        let z_a_data: Vec<Vec<f64>> =
            serde_json::from_value(btg["z_a"].clone()).unwrap();
        let z_b_data: Vec<Vec<f64>> =
            serde_json::from_value(btg["z_b"].clone()).unwrap();

        let n_rows = z_a_data.len();
        let n_cols = z_a_data[0].len();

        let z_a_flat: Vec<f32> = z_a_data.into_iter().flatten().map(|v| v as f32).collect();
        let z_b_flat: Vec<f32> = z_b_data.into_iter().flatten().map(|v| v as f32).collect();

        let ad_dev = <AB as Backend>::Device::default();
        let z_a: Tensor<AB, 2> = Tensor::from_data(
            TensorData::new(z_a_flat, [n_rows, n_cols]),
            &ad_dev,
        )
        .require_grad();
        let z_b: Tensor<AB, 2> = Tensor::from_data(
            TensorData::new(z_b_flat, [n_rows, n_cols]),
            &ad_dev,
        );
        // z_b NOT require_grad — it's the detached target

        let config = crate::loss::representation::BarlowTwinsConfig {
            lambda: 0.0051,
        };
        let loss = crate::loss::representation::barlow_twins_loss(z_a.clone(), z_b, &config);
        let grads = loss.backward();

        let z_a_grad = z_a.grad(&grads);
        assert!(
            z_a_grad.is_some(),
            "z_a should have gradients (it's the projected state)"
        );
        let grad_vals: Vec<f32> = z_a_grad.unwrap().to_data().to_vec().unwrap();
        let has_nonzero = grad_vals.iter().any(|&g| g.abs() > 1e-8);
        assert!(has_nonzero, "z_a gradients should be non-zero");
    }

    // ==== Symlog roundtrip ====

    #[test]
    fn symlog_matches_reference() {
        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let sl = &oracles["symlog"];

        let input = tensor_1d_from_json(&sl["input"]);
        let expected = tensor_1d_from_json(&sl["symlog"]);

        let result = rl4burn_nn::symlog::symlog(input);
        let diff: f32 = (result - expected).abs().max().into_scalar();
        assert!(diff < 1e-4, "symlog max diff = {diff}");
    }

    #[test]
    fn symlog_symexp_roundtrip_matches_reference() {
        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let sl = &oracles["symlog"];

        let input = tensor_1d_from_json(&sl["input"]);
        let expected = tensor_1d_from_json(&sl["roundtrip"]);

        let result = rl4burn_nn::symlog::symexp(rl4burn_nn::symlog::symlog(input));
        let vals: Vec<f32> = result.to_data().to_vec().unwrap();
        let exp_vals: Vec<f32> = expected.to_data().to_vec().unwrap();

        for (i, (&got, &exp)) in vals.iter().zip(exp_vals.iter()).enumerate() {
            let tol = exp.abs() * 1e-4 + 1e-6;
            assert!(
                (got - exp).abs() < tol,
                "roundtrip[{i}]: got {got}, expected {exp}"
            );
        }
    }

    // ==== Twohot encode/decode ====

    #[test]
    fn twohot_distribution_row_sums_match_reference() {
        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let th = &oracles["twohot"];

        let expected_sums: Vec<f64> =
            serde_json::from_value(th["row_sums"].clone()).unwrap();

        for (i, &s) in expected_sums.iter().enumerate() {
            assert!(
                (s - 1.0).abs() < 1e-5,
                "reference row_sum[{i}] = {s}, expected 1.0"
            );
        }
    }

    #[test]
    fn twohot_decode_matches_reference() {
        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let th = &oracles["twohot"];

        let values: Vec<f64> =
            serde_json::from_value(th["values"].clone()).unwrap();
        let expected_decoded: Vec<f64> =
            serde_json::from_value(th["decoded"].clone()).unwrap();

        let enc = rl4burn_nn::symlog::TwohotEncoder::new();
        let input_vals: Vec<f32> = values.iter().map(|&v| v as f32).collect();
        let len = input_vals.len();
        let input: Tensor<B, 1> = Tensor::from_data(
            TensorData::new(input_vals, [len]),
            &dev(),
        );
        let dist = enc.encode::<B>(input, &dev());
        let decoded = enc.decode::<B>(dist, &dev());
        let dec_vals: Vec<f32> = decoded.to_data().to_vec().unwrap();

        for (i, (&got, &exp)) in dec_vals.iter().zip(expected_decoded.iter()).enumerate() {
            let exp_f32 = exp as f32;
            let tol = exp_f32.abs() * 0.05 + 0.5;
            assert!(
                (got - exp_f32).abs() < tol,
                "twohot decode[{i}]: got {got}, expected {exp_f32} (input={})",
                values[i]
            );
        }
    }

    // ==== KL balancing ====

    #[test]
    fn kl_balance_matches_reference() {
        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let kl = &oracles["kl_balance"];

        let post = tensor_2d_from_json(&kl["posterior_logits"]);
        let prior = tensor_2d_from_json(&kl["prior_logits"]);

        let config = crate::loss::kl_balance::KlBalanceConfig {
            dyn_weight: 0.5,
            rep_weight: 0.1,
            free_bits: 1.0,
        };

        let loss: f32 = crate::loss::kl_balance::kl_balanced_loss(
            post, prior, &config,
        )
        .into_scalar();

        let expected = kl["total"].as_f64().unwrap() as f32;
        assert!(
            (loss - expected).abs() < 1e-2,
            "KL balance total {loss} != reference {expected}"
        );
    }

    #[test]
    fn kl_per_sample_matches_reference() {
        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let kl = &oracles["kl_balance"];

        let post = tensor_2d_from_json(&kl["posterior_logits"]);
        let prior = tensor_2d_from_json(&kl["prior_logits"]);

        // Verify dyn KL (sg(posterior) || prior) -- here we just test
        // forward KL since detach doesn't change values, only gradients.
        let dyn_kl = crate::loss::kl_balance::categorical_kl(
            post.clone(),
            prior.clone(),
        );

        let expected_dyn: Vec<f64> =
            serde_json::from_value(kl["dyn_kl_per_sample"].clone()).unwrap();
        let dyn_vals: Vec<f32> = dyn_kl.to_data().to_vec().unwrap();

        for (i, (&got, &exp)) in dyn_vals.iter().zip(expected_dyn.iter()).enumerate() {
            let exp_f32 = exp as f32;
            assert!(
                (got - exp_f32).abs() < 1e-3,
                "dyn_kl[{i}]: got {got}, expected {exp_f32}"
            );
        }
    }

    // ==== BT signal pair wiring (structural, not numerical) ====

    #[test]
    fn bt_signal_pair_invariants() {
        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let pair = &oracles["bt_signal_pair"];

        // The reference confirms:
        // 1. Input A is projector(state) WITH gradient
        assert_eq!(
            pair["bt_input_a_source"].as_str().unwrap(),
            "projector(concat(h_t, z_t))"
        );
        assert_eq!(pair["bt_input_a_requires_grad"].as_bool().unwrap(), true);

        // 2. Input B is encoder output, DETACHED
        assert_eq!(
            pair["bt_input_b_source"].as_str().unwrap(),
            "encoder(obs_t).detach()"
        );
        assert_eq!(pair["bt_input_b_requires_grad"].as_bool().unwrap(), false);

        // 3. BT is computed over B*T jointly
        assert_eq!(
            pair["bt_computed_over"].as_str().unwrap(),
            "B*T samples jointly, not per-timestep"
        );

        // 4. Projector is linear
        assert_eq!(
            pair["projector_type"].as_str().unwrap(),
            "linear (no activation, no norm)"
        );

        // 5. Input B dimension equals encoder output dimension
        assert_eq!(
            pair["input_b_dim_equals_encoder_output_dim"]
                .as_bool()
                .unwrap(),
            true
        );
    }

    // ==== Lambda returns ====

    #[test]
    fn lambda_returns_match_reference() {
        let oracles: serde_json::Value = serde_json::from_str(ORACLES).unwrap();
        let lr = &oracles["lambda_returns"];

        let rewards: Vec<f64> =
            serde_json::from_value(lr["rewards"].clone()).unwrap();
        let values: Vec<f64> =
            serde_json::from_value(lr["values"].clone()).unwrap();
        let continues: Vec<f64> =
            serde_json::from_value(lr["continues"].clone()).unwrap();
        let gamma = lr["gamma"].as_f64().unwrap() as f32;
        let lambda = lr["lambda"].as_f64().unwrap() as f32;
        let expected: Vec<f64> =
            serde_json::from_value(lr["returns"].clone()).unwrap();

        let horizon = rewards.len();
        let reward_tensors: Vec<Tensor<B, 1>> = rewards
            .iter()
            .map(|&r| Tensor::from_floats([r as f32], &dev()))
            .collect();
        let value_tensors: Vec<Tensor<B, 1>> = values
            .iter()
            .map(|&v| Tensor::from_floats([v as f32], &dev()))
            .collect();
        let cont_tensors: Vec<Tensor<B, 1>> = continues
            .iter()
            .map(|&c| Tensor::from_floats([c as f32], &dev()))
            .collect();

        let returns = crate::planning::imagination::lambda_returns(
            &reward_tensors,
            &value_tensors,
            &cont_tensors,
            gamma,
            lambda,
        );

        for t in 0..horizon {
            let got: f32 = returns[t].clone().into_scalar();
            let exp = expected[t] as f32;
            assert!(
                (got - exp).abs() < 1e-3,
                "lambda_return[{t}]: got {got}, expected {exp}",
            );
        }
    }
}
